    public static Book register(String title) {
        return new Book(UUID.randomUUID(), title, BookStatus.AVAILABLE);
    }

    public static Book reconstitute(UUID id, String title, BookStatus status) {
        return new Book(id, title, status);
    }

    // 신용조회에서 거절된 회원에게는 빌려주지 않는다. 거절되면 책 상태는 바뀌지 않는다
    public Loan loanTo(UUID memberId, LocalDate loanedAt, ReservationQueue reservations, CreditCheck creditCheck) {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.ON_LOAN) {
            throw new BookAlreadyOnLoanException(id);
        }
        if (!reservations.allowsLoanTo(memberId)) {
            throw new ReservedForOtherException(id);
        }
        if (!creditCheck.approved()) {
            throw new CreditRejectedException(memberId);
        }
        Loan loan = Loan.start(id, memberId, loanedAt, creditCheck);
        status = BookStatus.ON_LOAN;
        return loan;
    }

    // 대출 중인 책만 예약할 수 있다. 대출 가능한 책은 바로 빌리면 되고, 폐기된 책은 돌아오지 않는다
    public void checkReservable() {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.AVAILABLE) {
            throw new BookAvailableException(id);
        }
    }

    // 훼손되거나 분실된 책을 폐기한다. 대출 중인 책은 반납된 뒤에야 폐기할 수 있다
    public void discard() {
        if (status == BookStatus.ON_LOAN) {
            throw new BookOnLoanException(id);
        }
        status = BookStatus.DISCARDED;
    }

    // 반납 처리 자체는 Loan.returnBook이 맡는다. 여기서는 대출 중인 책만 다시 대출 가능 상태로 바꾼다.
    public void returnBook() {
        if (status != BookStatus.ON_LOAN) {
            throw new IllegalStateException("book is not on loan: " + id);
        }
        status = BookStatus.AVAILABLE;
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public BookStatus getStatus() {
        return status;
    }
}
